/** Pull text lines out of a PDF so NTSSA roster tables can be parsed.
 *  Dummy printouts use simple `(line) Tj` operators — those are enough.
 *  Real association PDFs go through pdf.js, grouping glyphs on a baseline
 *  so Club / Team / Age stay as lines.
 */

export function isPdfBytes(data: ArrayBuffer | Uint8Array): boolean {
  const u8 = data instanceof Uint8Array ? data : new Uint8Array(data);
  return u8.length >= 5 && u8[0] === 0x25 && u8[1] === 0x50 && u8[2] === 0x44 && u8[3] === 0x46 && u8[4] === 0x2d;
}

function unescapePdfString(s: string): string {
  return s.replace(/\\(.)/g, (_, c: string) => {
    if (c === "n") return "\n";
    if (c === "r") return "\r";
    if (c === "t") return "\t";
    return c;
  });
}

/** Text operators from a generated printout. No worker. */
export function extractTjLines(data: ArrayBuffer | Uint8Array): string[] {
  const text = new TextDecoder("latin1").decode(data instanceof Uint8Array ? data : new Uint8Array(data));
  const lines: string[] = [];
  const re = /\(([^\\()]*(?:\\.[^\\()]*)*)\)\s*Tj/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text))) {
    const line = unescapePdfString(m[1]).replace(/\s+/g, " ").trim();
    if (line) lines.push(line);
  }
  return lines;
}

function looksLikeNtssaLines(lines: string[]): boolean {
  const blob = lines.join(" ");
  return /north texas soccer association roster/i.test(blob);
}

async function extractPdfjsLines(bytes: Uint8Array): Promise<string[]> {
  const { getDocument, GlobalWorkerOptions } = await import("pdfjs-dist");
  if (typeof window !== "undefined" && !GlobalWorkerOptions.workerSrc) {
    GlobalWorkerOptions.workerSrc = new URL("pdfjs-dist/build/pdf.worker.min.mjs", import.meta.url).toString();
  }
  const loading = getDocument({
    data: bytes.slice(),
    isEvalSupported: false,
    useSystemFonts: true,
  });
  const pdf = await loading.promise;
  const lines: string[] = [];
  for (let p = 1; p <= pdf.numPages; p++) {
    const page = await pdf.getPage(p);
    const content = await page.getTextContent();
    const rows = new Map<number, Array<{ str: string; x: number }>>();
    for (const raw of content.items) {
      const it = raw as { str?: string; transform?: number[] };
      if (!it || typeof it.str !== "string" || !it.str.trim()) continue;
      const t = it.transform;
      const x = Array.isArray(t) && t.length >= 5 ? t[4] : 0;
      const y = Array.isArray(t) && t.length >= 6 ? t[5] : 0;
      const key = Math.round(y / 3) * 3;
      const list = rows.get(key) || [];
      list.push({ str: it.str, x });
      rows.set(key, list);
    }
    const pageLines = [...rows.entries()]
      .sort((a, b) => b[0] - a[0])
      .map(([, row]) =>
        row
          .sort((a, b) => a.x - b.x)
          .map((c) => c.str)
          .join(" ")
          .replace(/\s+/g, " ")
          .trim(),
      )
      .filter(Boolean);
    lines.push(...pageLines);
  }
  return lines;
}

export async function pdfTextLines(data: ArrayBuffer | Uint8Array): Promise<string[]> {
  const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
  const fromTj = extractTjLines(bytes);
  if (looksLikeNtssaLines(fromTj)) return fromTj;
  try {
    const viaPdfjs = await extractPdfjsLines(bytes);
    if (viaPdfjs.length) return viaPdfjs;
  } catch {
    /* dummy printouts still parse from the text operators */
  }
  if (fromTj.length) return fromTj;
  throw new Error("unreadable-pdf");
}
